/* EC913 NovaTech Mall visual system */
:root{--ec13-green:#58a638;--ec13-green-dark:#397b24;--ec13-navy:#17283d;--ec13-blue:#365795;--ec13-red:#ef2d0a;--ec13-yellow:#ffd62a;--ec13-text:#1c2734;--ec13-muted:#687384;--ec13-line:#e5e9ef;--ec13-bg:#f4f6f9;--ec13-white:#fff}
html{scroll-behavior:smooth}
body{background:var(--ec13-bg);color:var(--ec13-text);font-family:Inter,"Segoe UI",Roboto,Arial,sans-serif}
.ec13-container{width:min(1440px,calc(100% - 40px));margin:0 auto}
.ec13-topbar{background:var(--ec13-green-dark);color:#eaf7e5;font-size:12px}
.ec13-topbar .ec13-container{height:34px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.ec13-topbar span{display:flex;align-items:center;gap:8px}.ec13-topbar div{display:flex;gap:24px}.ec13-topbar a{color:#eaf7e5}
.ec13-main-header{background:var(--ec13-green)}
.ec13-head-main{min-height:92px;display:grid;grid-template-columns:240px minmax(280px,1fr) auto auto auto;align-items:center;gap:18px}
.ec13-logo{display:inline-flex;align-items:center;gap:10px;color:#fff;min-width:0}.ec13-logo img{display:block;max-width:220px;max-height:64px;object-fit:contain}.ec13-logo-mark{width:48px;height:48px;border-radius:14px;background:var(--ec13-red);display:grid;place-items:center;font-size:24px;box-shadow:0 8px 20px #1d4b2138}.ec13-logo>span:last-child{font-size:23px;font-weight:900;letter-spacing:-1px;line-height:.9}.ec13-logo>span b{color:#f9df2c}.ec13-logo small{display:block;margin-top:7px;font-size:10px;letter-spacing:2.2px;text-transform:uppercase;color:#e9f6e3}
.ec13-search{height:50px;background:#fff;border-radius:8px;display:flex;overflow:hidden;box-shadow:0 7px 20px #214e2630}.ec13-search input{flex:1;min-width:0;border:0;padding:0 20px;font:inherit;color:var(--ec13-text);outline:0}.ec13-search button{width:62px;border:0;background:#fff;color:var(--ec13-green-dark);font-size:18px;cursor:pointer}
.ec13-head-support{display:flex;align-items:center;gap:10px;color:#fff;white-space:nowrap}.ec13-head-support>i{font-size:26px}.ec13-head-support span,.ec13-icon-action span{font-size:11px}.ec13-head-support b{display:block;font-size:15px;margin-top:4px}
.ec13-icon-action{position:relative;border:0;background:var(--ec13-navy);color:#fff;border-radius:8px;min-width:68px;height:58px;padding:8px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;cursor:pointer}.ec13-icon-action>i{font-size:19px}.ec13-icon-action em{position:absolute;right:8px;top:-8px;min-width:22px;height:22px;border-radius:20px;background:var(--ec13-red);font:700 11px/22px Inter;font-style:normal}
.ec13-menu-toggle{display:none;border:0;background:var(--ec13-navy);color:#fff;width:46px;height:46px;border-radius:8px;font-size:18px}
.ec13-nav{background:var(--ec13-navy);box-shadow:0 4px 12px #15213121}.ec13-nav .ec13-container{display:flex;align-items:stretch;min-height:58px}.ec13-nav a,.ec13-nav-category{display:flex;align-items:center;gap:7px;padding:0 26px;color:#fff;font-weight:700;border:0;background:transparent;font:700 15px Inter;cursor:pointer}.ec13-nav a:hover,.ec13-nav a.active{background:var(--ec13-red)}.ec13-nav-category{width:250px;justify-content:flex-start;background:var(--ec13-blue);font-size:17px;text-transform:uppercase}.ec13-nav-category i:last-child{margin-left:auto;font-size:11px}.ec13-admin-link{margin-left:auto!important}
.ec13-hero-shell{padding:24px 0;background:#fff}.ec13-hero-layout{display:grid;grid-template-columns:250px minmax(0,1fr) 270px;gap:16px;align-items:stretch}
.ec13-category-menu{border:1px solid var(--ec13-line);background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 10px 25px #1f2d3d12}.ec13-category-menu h2{display:none}.ec13-category-menu a{min-height:49px;padding:0 16px;display:flex;align-items:center;justify-content:space-between;color:#273344;border-bottom:1px solid #eff1f4;font-size:13px}.ec13-category-menu a span{display:flex;align-items:center;gap:12px}.ec13-category-menu a span i{width:20px;text-align:center;color:var(--ec13-green);font-size:16px}.ec13-category-menu a>i{font-size:10px;color:#a1a9b4}.ec13-category-menu a:hover,.ec13-category-menu a.is-active{background:#edf7e9;color:var(--ec13-green-dark);font-weight:700}.ec13-category-menu a:last-child{border:0}
.ec13-hero-slider{position:relative;min-height:460px;border-radius:8px;overflow:hidden;background:var(--ec13-yellow)}.ec13-hero-slider article{position:absolute;inset:0;opacity:0;visibility:hidden;transition:.45s}.ec13-hero-slider article.is-active{opacity:1;visibility:visible}.ec13-hero-slider article>img{width:100%;height:100%;object-fit:cover}.ec13-hero-copy{position:absolute;z-index:2;left:6%;top:50%;transform:translateY(-50%);width:min(42%,440px);color:var(--ec13-navy)}.ec13-hero-copy>span{display:inline-block;padding:7px 12px;border-radius:4px;background:var(--ec13-navy);color:#fff;font-size:11px;font-weight:800;letter-spacing:1.2px}.ec13-hero-copy h1{margin:16px 0 12px;font-size:clamp(30px,3.1vw,50px);line-height:1.04;letter-spacing:-1.8px}.ec13-hero-copy p{font-size:16px;line-height:1.6;margin:0 0 22px;max-width:380px}.ec13-hero-copy a{display:inline-flex;align-items:center;gap:9px;padding:13px 20px;border-radius:6px;background:var(--ec13-red);color:#fff;font-weight:800}.ec13-slider-dots{position:absolute;bottom:16px;left:50%;transform:translateX(-50%);display:flex;gap:7px}.ec13-slider-dots button{width:8px;height:8px;border-radius:10px;border:0;background:#ffffffb8;padding:0;transition:.2s}.ec13-slider-dots button.is-active{width:26px;background:var(--ec13-red)}
.ec13-side-promos{display:grid;grid-template-rows:1fr 1fr;gap:16px}.ec13-side-promos>a{position:relative;overflow:hidden;border-radius:8px;background:var(--ec13-navy);min-height:0}.ec13-side-promos img{width:100%;height:100%;object-fit:cover}.ec13-side-promos span{position:absolute;inset:auto 14px 14px;padding:11px;border-radius:6px;background:#07172abf;color:#fff;backdrop-filter:blur(5px)}.ec13-side-promos small,.ec13-side-promos b,.ec13-side-promos em{display:block}.ec13-side-promos small{font-size:9px;font-weight:800;color:#65e1ff;letter-spacing:.8px}.ec13-side-promos b{font-size:15px;margin:5px 0}.ec13-side-promos em{font-size:11px;font-style:normal;color:#dce6ef}
.ec13-benefits{background:#fff;border-top:1px solid var(--ec13-line);border-bottom:1px solid var(--ec13-line)}.ec13-benefits .ec13-container{display:grid;grid-template-columns:repeat(4,1fr)}.ec13-benefits article{min-height:100px;padding:20px 28px;display:flex;align-items:center;gap:16px;border-right:1px solid var(--ec13-line)}.ec13-benefits article:last-child{border:0}.ec13-benefits i{font-size:28px;color:var(--ec13-red)}.ec13-benefits h3{margin:0 0 5px;font-size:14px}.ec13-benefits p{margin:0;color:var(--ec13-muted);font-size:12px}
.ec13-section{padding:42px 0}.ec13-section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:22px}.ec13-section-head span{display:block;margin-bottom:6px;color:var(--ec13-green-dark);font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:1.5px}.ec13-section-head h2{margin:0;font-size:27px;letter-spacing:-.7px}.ec13-section-head h2:after{content:"";display:block;width:52px;height:4px;margin-top:10px;border-radius:4px;background:var(--ec13-red)}.ec13-section-head>a{color:var(--ec13-green-dark);font-size:13px;font-weight:700}
.ec13-categories{background:#f5f7fa}.ec13-category-grid{display:grid;grid-template-columns:repeat(6,1fr);background:#fff;border:1px solid var(--ec13-line);border-radius:10px;overflow:hidden}.ec13-category-grid>a{padding:20px 12px;text-align:center;border-right:1px solid var(--ec13-line);transition:.2s}.ec13-category-grid>a:nth-child(6n){border-right:0}.ec13-category-grid>a:hover{background:#f0f8ed;transform:translateY(-3px)}.ec13-category-grid>a>span{height:86px;display:grid;place-items:center}.ec13-category-grid img{max-width:100%;max-height:80px;object-fit:contain}.ec13-category-grid b,.ec13-category-grid small{display:block}.ec13-category-grid b{margin-top:10px;color:var(--ec13-text);font-size:13px}.ec13-category-grid small{margin-top:5px;color:var(--ec13-muted);font-size:10px}
